import json

# Inspect the pristine read result and any applied writes
reads = data.get('reads', [])
writes = data.get('writes', [])

facts = {
    'pristine_read': None,
    'applied_writes': []
}

if reads:
    pristine = reads[-1].get('result')
    if isinstance(pristine, str):
        try:
            pristine = json.loads(pristine)
        except:
            pass
    facts['pristine_read'] = pristine

for w in writes:
    facts['applied_writes'].append({
        'api': w.get('api'),
        'name': w.get('name'),
        'args': w.get('args'),
        'result': w.get('result')
    })

print(json.dumps({'queries': [], 'facts': facts}))
